     "urdu": "#include <iostream.h>\n#include<conio.h>\nint main()\n{\nint X;\ncout << \"Enter a number: \";\ncin >> X;\nif (X > 100)\ncout << X << \"is greater than 100\" << endl;\nelse if (X < 50)\ncout << X << \"is less than 50\" << endl;\nelse\ncout << X << \" is between 50 and 100\" << endl;\ngetch();\nreturn 0;\n}",
     "pashto": "#include <iostream.h>\n#include<conio.h>\nint main()\n{\nint X;\ncout << \"Enter a number: \";\ncin >> X;\nif (X > 100)\ncout << X << \"is greater than 100\" << endl;\nelse if (X < 50)\ncout << X << \"is less than 50\" << endl;\nelse\ncout << X << \" is between 50 and 100\" << endl;\ngetch();\nreturn 0;\n}",
