     "urdu": "#include <iostream.h>\n#include<conio.h>\nint main()\n{\nfor (int i=1; i<6; i++)\ncout << \"PAKISTAN\"<<endl;\ngetch();\nreturn 0;\n}",
     "pashto": "#include <iostream.h>\n#include<conio.h>\nint main()\n{\nfor (int i=1; i<6; i++)\ncout << \"PAKISTAN\"<<endl;\ngetch();\nreturn 0;\n}",
