     "urdu": "PAKISTAN\nPAKISTAN\nPAKISTAN\nPAKISTAN\nPAKISTAN",
     "pashto": "PAKISTAN\nPAKISTAN\nPAKISTAN\nPAKISTAN\nPAKISTAN",
