     "text": "// constructors overloading\n#include <iostream.h>\n#include <conio.h>\nclass CRectangle\n{\nint width, length;\npublic:\nCRectangle()\n{\nwidth = 5;\nlength = 15;\n}\nCRectangle (int a, int b)\n{\nwidth = a;\nlength = b;\n}\nint area()\n{\nreturn (width*length);\n}\n};\nint main()\n{\nCRectangle r1 (5,14);\nCRectangle r2;\ncout << \"Area of first rectangle: \" << r1.area() << endl;\ncout << \"Area of second rectangle: \" << r2.area() << endl;\ngetch();\nreturn 0;\n}",
